// Eyebrow, AS GRAPH SOURCE (#3684, epic #3604) — a foundational shared/ui typography primitive authored as DATA. Its
// `provides: "@/shared/ui/typography/Eyebrow"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). Transcribed verbatim; deps stay registered code.
// Eyebrow — the small mono/dim/uppercase label used above section headings and panel titles across the
// app (dock heads, card headers, section labels). A thin preset over Text, not a separate style system.
import type { ReactNode, ElementType, CSSProperties } from "react";
import { Text } from "@/shared/ui/typography/Text";

export interface EyebrowProps {
  children?: ReactNode;
  /** Font size in px. Default 10. */
  size?: number;
  /** The rendered element (default "span"). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  [key: string]: unknown;
}

/** Eyebrow — a small mono, dim, uppercase, letter-spaced label. See {@link EyebrowProps}. */
export function Eyebrow({ children, size = 10, as = "span", style, ...rest }: EyebrowProps) {
  return (
    <Text
      mono
      size={size}
      tone="dim"
      as={as}
      style={{ letterSpacing: ".08em", textTransform: "uppercase", ...style }}
      {...rest}
    >
      {children}
    </Text>
  );
}
